## Why This Is Asked
Tests ability to frame a sign-assignment problem as a DP and implement both memoization and tabulation, a common interview pattern.

## Key Concepts
- DP state reduction to subset sum
- Space optimization with a 1D array
- Memoization vs bottom-up trade-offs

## Code Example
```javascript
// Tabulation and Memo versions
function countTargetSumTab(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const dp = Array(target+1).fill(0);
  dp[0] = 1;
  for (const n of nums) {
    for (let t = target; t >= n; t--) dp[t] += dp[t-n];
  }
  return dp[target];
}

function countTargetSumMemo(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const memo = new Map();
  function dfs(i, sum){
    if (sum > target) return 0;
    if (i === nums.length) return sum === target ? 1 : 0;
    const key = i+':'+sum;
    if (memo.has(key)) return memo.get(key);
    const res = dfs(i+1, sum+nums[i]) + dfs(i+1, sum);
    memo.set(key, res);
    return res;
  }
  return dfs(0,0);
}
```

## Why This Is Asked

This problem tests practical DP skills: counting subsets, managing zeros, and comparing memoization vs tabulation.

## Key Concepts

- Subset sum counting
- Top-down memoization
- Bottom-up tabulation
- Modulo arithmetic and zero handling

## Code Example

```javascript
function countSubsetsTopDown(nums, target) {
  const n = nums.length;
  const memo = Array.from({length: n+1}, () => new Map());
  function dfs(i, t){
    if (t === 0) return 1;
    if (i === n) return 0;
    const key = t;
    if (memo[i].has(key)) return memo[i].get(key);
    let res = dfs(i+1, t);
    if (t >= nums[i]) res = (res + dfs(i+1, t - nums[i]));
    memo[i].set(key, res);
    return res;
  }
  return dfs(0, target);
}
function countSubsetsBottomUp(nums, target){
  const MOD = 1000000007;
  const dp = new Array(target+1).fill(0);
  dp[0] = 1;
  for (const v of nums){
    for (let w = target; w >= v; w--){
      dp[w] = (dp[w] + dp[w - v]) % MOD;
    }
  }
  return dp[target];
}
``` 

